if(totalMatch) {
    var totalChapters = parseInt(totalMatch[1]);
    var totalPages = Math.ceil(totalChapters / 100);
    for(var i = 1; i <= totalPages; i++) {
        tocUrls.push(baseUrl + 'index_' + i + '.html');
    }
}
