@js:(function(){
var kw=String(key);
var webJs='(function(){'
+'var kw='+JSON.stringify(kw)+';'
+'try{'
+'var t=document.querySelector("input[name=_t]");'
+'if(!t){return "<html><body>ERR:NO_TOKEN</body></html>";}'
+'var _t=t.value;'
+'var sig=window.__signData(kw,_t);'
+'if(!sig||!sig.s){return "<html><body>ERR:NO_SIGN</body></html>";}'
+'var x=new XMLHttpRequest();'
+'x.open("POST","/?action=search",false);'
+'x.setRequestHeader("Content-Type","application/x-www-form-urlencoded");'
+'x.send("_t="+encodeURIComponent(_t)+"&_ts="+sig.ts+"&_s="+sig.s+"&keyword="+encodeURIComponent(kw));'
+'if(x.status!==200){return "<html><body>ERR:HTTP"+x.status+"</body></html>";}'
+'return x.responseText;'
+'}catch(e){return "<html><body>ERR:"+e.message+"</body></html>";}'
+'})()';
return 'https://www.rrssk.com/0005.html,'+JSON.stringify({webView:true,webJs:webJs});
})()

